INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(22601, 'Matthew 17:16', 'Matthew', 17, 16, '&nbsp;ما هغه ستا مريدانو له راوستو خو هغوئ روغ نۀ کړے شو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22602, 'Matthew 17:17', 'Matthew', 17, 17, '&nbsp;عيسىٰ جواب ورکړو، ”اے بې‌ايمانه او بدکاره پيړۍ، زۀ به ترڅو تاسو سره يم او زۀ به ترڅو تاسو زغمم؟ هغه ما له دلته راولئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22603, 'Matthew 17:18', 'Matthew', 17, 18, '&nbsp;بيا عيسىٰ هغه پيرے ورټلو نو هغه يې پرېښودو او سمدستى هغه هلک روغ شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22604, 'Matthew 17:19', 'Matthew', 17, 19, '&nbsp;د دې نه پس مريدان عيسىٰ له يواځې راغلل او تپوس يې وکړو چې، ”دا مونږ ولې نۀ شُو شړلے؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22605, 'Matthew 17:22', 'Matthew', 17, 22, '&nbsp;کله چې هغوئ په ګليل کښې يو ځائ وُو نو عيسىٰ ورته وفرمائيل چې، ”اِبن آدم به د دشمنانو لاسونو ته حواله کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22606, 'Matthew 17:23', 'Matthew', 17, 23, '&nbsp;هغوئ به دے قتل کړى، په درېمه ورځ به هغه بيا راژوندے شى.“ نو په دې اورېدو هغوئ ډېر غمژن شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22607, 'Matthew 17:24', 'Matthew', 17, 24, '&nbsp;کله چې دوئ کفرنحُوم ته راغلل نو د خُدائ د کور خزانچى پطروس له راغلو او تپوس يې ترې وکړو چې، ”ولې ستا اُستاذ د خُدائ د کور محصُول ورکوى څۀ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22608, 'Matthew 17:25', 'Matthew', 17, 25, '&nbsp;پطروس ورته ووئيل چې، ”هغه يې ورکوى.“ خو کله چې پطروس دننه لاړو نو عيسىٰ د هغۀ د وينا نه وړاندې وفرمائيل چې، ”اے شمعونه، تۀ په دې باره کښې څۀ وائې چې د دُنيا بادشاهان د چا نه محصُول او ماليه اخلى، د خپلو خلقو نه کۀ د پردو نه؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22609, 'Matthew 17:26', 'Matthew', 17, 26, '&nbsp;پطروس جواب ورکړو چې، ”د پردو نه.“ عيسىٰ وفرمائيل، ”نو بيا خو د دوئ خپل خلق معاف دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22610, 'Matthew 17:27', 'Matthew', 17, 27, '&nbsp;خو هرکله چې مونږ بد نۀ خوښوو نو تۀ لاړ شه، د درياب په اوبو کښې کُنډه واچوه او کوم کب چې تۀ اول ونيسې، د هغۀ خولۀ کولاو کړه، نو تۀ به په کښې يوه د سپينو زرو سيکه ومومې. هغه يوسه او ور يې کړه، دا به زما او ستا دواړو محصُول پوره کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22611, 'Matthew 18:1', 'Matthew', 18, 1, '&nbsp;په هغه وخت مريدان عيسىٰ له راغلل او تپوس يې ترې وکړو چې، ”د آسمان په بادشاهۍ کښې د ټولو نه لوئ څوک دے؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22612, 'Matthew 18:2', 'Matthew', 18, 2, '&nbsp;هغۀ يو ماشوم راوبللو او د هغوئ په وړاندې يې ودرولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22613, 'Matthew 18:3', 'Matthew', 18, 3, '&nbsp;او ورته يې وفرمائيل چې، ”زۀ تاسو ته رښتيا وايم ترڅو چې تاسو خپل ځان بدل نۀ کړئ او د ماشومانو په شان نۀ شئ نو تاسو به هيڅکله هم په آسمانى بادشاهۍ کښې داخل نۀ شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22614, 'Matthew 18:4', 'Matthew', 18, 4, '&nbsp;هر هغه څوک چې ځان د دې ماشوم په شان عاجز کړى نو هغه به په آسمانى بادشاهۍ کښې د ټولو نه لوئ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22615, 'Matthew 18:5', 'Matthew', 18, 5, '&nbsp;او څوک چې زما په نوم داسې ماشوم قبول کړى هغه ما قبلوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22616, 'Matthew 18:6', 'Matthew', 18, 6, '&nbsp;خو هر هغه څوک چې په دې وړو ماشومانو کښې چې په ما يې ايمان راوړے دے، يو ته تيندک ورکوى، نو د هغۀ دپاره دا بهتره ده چې د هغۀ په غاړه کښې د ژرندې پل واچولے شى او په سمندر کښې ډوب شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22617, 'Matthew 18:7', 'Matthew', 18, 7, '&nbsp;په دُنيا دې افسوس وى چې انسان د دې څيزونو په وجه ګناه کوى. دا څيزونه به ضرور راځى خو افسوس په هغۀ د چا د لاسه چې به پېښږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22618, 'Matthew 18:8', 'Matthew', 18, 8, '&nbsp;کۀ چرې ستا لاس يا پښه تا له تيندک درکوى، نو ځان نه يې پرې کړه او ګزار يې کړه ستا دپاره به دا ښۀ وى چې تۀ په ابدى ژوندون کښې شل ګوډ ننوځې، په ځائ د دې چې تۀ په دواړو لاسو پښو سم يې او ابدى اور ته واچولے شې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22619, 'Matthew 18:9', 'Matthew', 18, 9, '&nbsp;او کۀ ستا سترګه تا ګناه ته ولمسوى نو وې باسه او وې غورزوه. ستا دپاره به دا ښۀ وى چې په يوې سترګې سره په ابدى ژوندون کښې داخل شې، په ځائ د دې چې په دواړو سترګو روغ يې او د دوزخ اور ته وغورزولے شې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22620, 'Matthew 18:10', 'Matthew', 18, 10, '&nbsp;خبردار، په دې وړو کښې يو ته هم سپک مۀ ګورئ. زۀ تاسو ته دا وايم چې د دوئ فرښتې په آسمان کښې هر وخت زما د آسمانى پلار په حضور کښې موجودې وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22621, 'Matthew 18:11', 'Matthew', 18, 11, '&nbsp;ځکه چې اِبن آدم د دې دپاره راغلے دے چې ورک شوو ته خلاصون ورکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22622, 'Matthew 18:12', 'Matthew', 18, 12, '&nbsp;ستاسو څۀ خيال دے؟ فرض کړئ چې د يو سړى سل ګډې دى. کۀ په هغې کښې يوه بې‌لارې شى، ولې هغه به دا نورې يو کم سل د هغې يوې د لټولو دپاره د غرۀ په خوا کښې پرې نۀ ږدى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22623, 'Matthew 18:13', 'Matthew', 18, 13, '&nbsp;او چې کله هغه دا بيا مومى نو زۀ تاسو ته رښتيا وايم چې د هغې په موندلو به هغه د دې نورو يو کم سلو نه چې بې‌لارې شوې نۀ دى، زيات خوشحاله شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22624, 'Matthew 18:14', 'Matthew', 18, 14, '&nbsp;هم دغه شان ستاسو د آسمانى پلار دا رضا نۀ ده چې د دې ماشومانو نه دې يو هم هلاک شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22625, 'Matthew 18:15', 'Matthew', 18, 15, '&nbsp;کۀ چرې ستاسو يو ورور ستاسو خلاف څۀ ګناه وکړى نو لاړ شئ او هغه په پرده کښې په دې ملامته کړئ او کۀ هغه تاسو ته غوږ کېږدى نو تاسو خپل ورور دوباره وموندلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22626, 'Matthew 18:16', 'Matthew', 18, 16, '&nbsp;خو کۀ هغه ستاسو خبره وانۀ ورى نو بيا يو يا دوه کسان نور د ځان سره ملګرى کړئ د دې دپاره چې هره خبره د دوو يا د درېو ګواهانو په وړاندې ثابته کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22627, 'Matthew 18:17', 'Matthew', 18, 17, '&nbsp;کۀ هغه د هغوئ هم وانۀ ورى نو دا خبره جماعت ته وړاندې کړئ او کۀ چرې هغه د جماعت خبره هم ونۀ منى نو بيا د هغۀ سره داسې سلوک وکړئ لکه چې د يو غېر يهودى، يا محصولچى سره کولے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22628, 'Matthew 18:18', 'Matthew', 18, 18, '&nbsp;زۀ تاسو ته دا وايم، هر څۀ چې تاسو په زمکه منع کړئ هغه به په آسمان کښې هم منع شى او څۀ چې تاسو په زمکه روا کړئ هغه به په آسمان کښې هم روا شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22629, 'Matthew 18:19', 'Matthew', 18, 19, '&nbsp;زۀ تاسو ته بيا دا وايم، کۀ چرې په تاسو کښې دوه کسان په يوه خبره متفِق شى هغوئ چې څۀ سوال وکړى نو زما آسمانى پلار به هغه ورکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22630, 'Matthew 18:20', 'Matthew', 18, 20, '&nbsp;نو کۀ چرې دوه يا درې تنه چرته هم زما په نوم يو ځائ شى نو زۀ به د دوئ په مينځ کښې يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22631, 'Matthew 18:21', 'Matthew', 18, 21, '&nbsp;بيا پطروس عيسىٰ له راغلو او تپوس يې وکړو، ”مالِکه، کۀ زما ورور زما خلاف څۀ بد کوى نو زۀ به يې څو ځله معاف کوم؟ تر اووۀ ځلو پورې څۀ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22632, 'Matthew 18:22', 'Matthew', 18, 22, '&nbsp;عيسىٰ جواب ورکړو، ”زۀ دا نۀ وايم چې اووۀ ځله، زۀ دا وايم چې اويا وارې اووۀ ځله،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22633, 'Matthew 18:23', 'Matthew', 18, 23, '&nbsp;نو په دې وجه د آسمان بادشاهى لکه د هغه بادشاه په شان ده چې يو ځلې يې د خپلو نوکرانو سره حساب شروع کړو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22634, 'Matthew 18:24', 'Matthew', 18, 24, '&nbsp;نو په اول سر کښې يو سړے داسې پېښ شو چې د هغۀ قرضه په لکونو کښې وه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22635, 'Matthew 18:25', 'Matthew', 18, 25, '&nbsp;خو د هغۀ سره هيڅ هم نۀ وُو. نو د هغۀ مالِک دا حکم وکړو چې هغه دې سره د ښځې، اولاد او هر څۀ مال حال چې لرى خرڅ کړے شى او قرض دې ترې پوره کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22636, 'Matthew 18:26', 'Matthew', 18, 26, '&nbsp;سړے د خپل مالِک په پښو پرېوتو او وې وئيل چې ما ته صبر وکړه، زۀ به ستا ټول قرض خلاص کړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22637, 'Matthew 18:27', 'Matthew', 18, 27, '&nbsp;نو د هغۀ د مالِک په زړۀ کښې هغۀ ته رحم راغلو هغۀ هغه آزاد کړو او قرض يې ورته وبخښلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22638, 'Matthew 18:28', 'Matthew', 18, 28, '&nbsp;خو هر کله چې دا نوکر بهر راووتو نو د خپلو ملګرو نوکرانو نه يو نوکر ورسره مِلاو شو په چا چې د دۀ سل ديناره قرض وُو. هغه يې راونيوو، او په مرۍ ورته غلے شو او ورته يې ووئيل چې زما قرض ما ته واپس کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22639, 'Matthew 18:29', 'Matthew', 18, 29, '&nbsp;نو هغه ملګرے نوکر يې په پښو پرېوتو او دۀ ته يې مِنت وکړو چې ما ته صبر وکړه، زۀ به ستا قرض تا ته واپس کړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22640, 'Matthew 18:30', 'Matthew', 18, 30, '&nbsp;خو هغۀ ورسره ونۀ منله او په قېدخانه کښې يې واچولو ترڅو چې قرض واپس نۀ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22641, 'Matthew 18:31', 'Matthew', 18, 31, '&nbsp;نورو نوکرانو چې دا حال وليدلو نو ډېر خفه شول. هغوئ خپل مالِک له لاړل او ټوله قيصه يې ورته تيره کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22642, 'Matthew 18:32', 'Matthew', 18, 32, '&nbsp;هغۀ دا نوکر راوبللو او ورته يې ووئيل چې اے بد کاره، چې کله تا ما ته مِنت وکړو نو ما درته ټول قرض وبخښلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22643, 'Matthew 18:33', 'Matthew', 18, 33, '&nbsp;ولې په تا کښې دومره سړيتوب نۀ وو چې په خپل ملګرى نوکر دې داسې رحم کړے وے لکه چې ما په تا وکړو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22644, 'Matthew 18:34', 'Matthew', 18, 34, '&nbsp;د هغۀ مالِک ډېر غصه شو او دے يې د قېدخانې مشر ته حواله کړو ترڅو چې يې ټول قرض واپس کړے نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22645, 'Matthew 18:35', 'Matthew', 18, 35, '&nbsp;کۀ چرې تاسو خپل ورور د زړۀ د اخلاصه معاف نۀ کړئ نو زما آسمانى پلار به هم تاسو هر يو سره داسې کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22646, 'Matthew 19:1', 'Matthew', 19, 1, '&nbsp;څۀ وخت چې عيسىٰ دا خبرې خلاصې کړې نو د ګليل نه روان شو او د اُردن نه پورې غاړه د يهوديه علاقې ته لاړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22647, 'Matthew 19:2', 'Matthew', 19, 2, '&nbsp;ګڼ خلق ورپسې وُو او هغۀ هغوئ هلته روغ کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22648, 'Matthew 19:3', 'Matthew', 19, 3, '&nbsp;نو ځينې فريسيان راغلل او د آزمېښت په طور يې ترې دا تپوس وکړو، ”ولې يو سړى ته دا روا دى چې په هره وجه چې وى خپله ښځه طلاقه کړى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22649, 'Matthew 19:4', 'Matthew', 19, 4, '&nbsp;هغۀ په جواب کښې ورته وفرمائيل چې، ”ولې تاسو دا نۀ دى لوستى چې خالق په اول سر کښې هغوئ نر او ښځه پېدا کړل؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22650, 'Matthew 19:5', 'Matthew', 19, 5, '&nbsp;په دې وجه به سړے خپل مور پلار پرېږدى او د خپلې ښځې سره به يو ځائ شى، او دا دواړه به يو بدن شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
