(22654, 'Matthew 19:9', 'Matthew', 19, 9, '&nbsp;زۀ تاسو ته وايم چې کۀ څوک بغېر د زناکارۍ د جرم نه په بله څۀ وجه خپلې ښځې له طلاق ورکړى او بل وادۀ وکړى نو هغه زنا کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22655, 'Matthew 19:10', 'Matthew', 19, 10, '&nbsp;مريدانو عيسىٰ ته ووئيل، ”کۀ د سړى د خپلې ښځې سره دا حال وى نو دا به ښۀ وى چې څوک دې بلکل وادۀ نۀ کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22656, 'Matthew 19:11', 'Matthew', 19, 11, '&nbsp;د دې په جواب کښې عيسىٰ وفرمائيل چې، ”خبره داسې ده چې هر څوک يې نۀ شى منلے خو صرف هغه خلق چې خُدائ پاک ورته د زغملو طاقت ورکړے وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22657, 'Matthew 19:12', 'Matthew', 19, 12, '&nbsp;ځينې داسې خلق دى چې د مور د ګېډې نه يا خو خصى پېدا دى او يا بنى آدمو خصى کړى دى، خو ځينې داسې دى چې هغوئ خپل ځانونه د آسمان د بادشاهۍ دپاره خصى کوى. څوک يې چې منلے شى هغه دې ومنى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22658, 'Matthew 19:13', 'Matthew', 19, 13, '&nbsp;يوه ورځ هغوئ عيسىٰ له ماشومان راوستل چې د برکت دپاره لاس پرې کېږدى، خو د هغۀ مريدانو هغه خلق ورټل چا چې راوستل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
