(22660, 'Matthew 19:15', 'Matthew', 19, 15, '&nbsp;بيا هغۀ خپل لاسونه د هغوئ په سر د برکت دپاره راښکل او روان شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22661, 'Matthew 19:16', 'Matthew', 19, 16, '&nbsp;او بيا يو سړے عيسىٰ له راغلو او تپوس يې ترې وکړو، ”اُستاذه، زۀ داسې کومه نېکى وکړم چې د ابدى ژوندون وارث شم؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22662, 'Matthew 19:17', 'Matthew', 19, 17, '&nbsp;عيسىٰ ورته وفرمائيل، ”د نېکۍ په حقله ولې تپوس کوې؟ نېک خو يواځې يو ذات دے، خو کۀ تۀ غواړې چې ابدى ژوندون حاصل کړې نو د موسىٰ د شريعت په حکمونو عمل کوه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22663, 'Matthew 19:18', 'Matthew', 19, 18, '&nbsp;هغه سړى تپوس وکړو چې، ”کوم حُکمونه؟“ عيسىٰ ورته وفرمائيل، ”قتل مۀ کوئ. زنا مۀ کوئ. غلا مۀ کوئ. د دروغو ګواهى مۀ ورکوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22664, 'Matthew 19:19', 'Matthew', 19, 19, '&nbsp;د مور پلار عزت کوئ او د خپل ګاونډى سره د خپل ځان په شان مينه ساتئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22665, 'Matthew 19:20', 'Matthew', 19, 20, '&nbsp;هغه ځوان جواب ورکړو چې، ”ما په دې ټولو عمل کړے دے خو په ما کښې د څۀ کمے دے؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22666, 'Matthew 19:21', 'Matthew', 19, 21, '&nbsp;عيسىٰ ورته وفرمائيل، ”کۀ تۀ کامِل کېدل غواړې نو لاړ شه، خپل ټول مال حال خرڅ کړه او خوارانو له يې ورکړه، نو بيا به تۀ آسمانى خزانې ومومې. بيا راځه، او په ما پسې شه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
