(22678, 'Matthew 20:3', 'Matthew', 20, 3, '&nbsp;بيا کچه غرمه هغه بهر ووتو نو په بازار کښې يې يو څو اوزګار کسان نور وليدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
